# Game status categories
# Change the values as you see fit
STATUS_WIN = 'win'
STATUS_LOSE = 'lose'
STATUS_ONGOING = 'ongoing'


class Hangman:
    def __init__(self, word):
        self.word = word
        self.remaining_guesses = 9
        self.status = STATUS_ONGOING
        self._guessed = set()

    def guess(self, char):
        if self.status != STATUS_ONGOING:
            raise ValueError("The game has already ended.")

        is_new_correct = char in self.word and char not in self._guessed
        self._guessed.add(char)

        if not is_new_correct:
            self.remaining_guesses -= 1

        if self._all_revealed():
            self.status = STATUS_WIN
        elif self.remaining_guesses < 0:
            self.status = STATUS_LOSE

    def _all_revealed(self):
        return all(char in self._guessed for char in self.word)

    def get_masked_word(self):
        return ''.join(
            char if char in self._guessed else '_' for char in self.word
        )

    def get_status(self):
        return self.status
